SCHEMA = """
CREATE TABLE IF NOT EXISTS macro_series (
    series_id TEXT NOT NULL,
    date TEXT NOT NULL,
    value REAL,
    PRIMARY KEY (series_id, date)
);
CREATE TABLE IF NOT EXISTS macro_meta (
    series_id TEXT PRIMARY KEY,
    fetched_at TEXT NOT NULL
);
"""


def fetch_series(series_id: str, api_key: str, units: str = "lin", limit: int = 260,
                 *, observation_start: str | None = None, include_missing: bool = False) -> list:
    """[(fecha, valor), ...] más reciente primero. Descarta observaciones sin
    dato ('.' es como FRED marca los huecos)."""
    params = {
        "series_id": series_id, "api_key": api_key, "file_type": "json",
        "sort_order": "desc", "limit": limit, "units": units,
    }
    if observation_start:
        params["observation_start"] = observation_start
    resp = requests.get(FRED_BASE_URL, params=params, timeout=20)
    if resp.status_code in (400, 401, 403):
        raise ValueError("FRED ha rechazado la petición (revisa que la API key sea correcta)")
    resp.raise_for_status()
    data = resp.json()
    observations = data.get("observations", [])
    return [(o["date"], None if o.get("value") in (None, ".") else float(o["value"]))
            for o in observations if include_missing or o.get("value") not in (None, ".")]


def upsert_series(series_id: str, observations: list):
    fetched_at = datetime.now(UTC).isoformat()
    with storage.get_connection() as conn:
        conn.executescript(SCHEMA)
        conn.executemany(
            "INSERT OR REPLACE INTO macro_series (series_id, date, value) VALUES (?,?,?)",
            [(series_id, date, value) for date, value in observations],
        )
        conn.execute(
            "INSERT OR REPLACE INTO macro_meta (series_id, fetched_at) VALUES (?,?)",
            (series_id, fetched_at),
        )
        conn.commit()


def get_series_history(series_id: str) -> pd.DataFrame:
    with storage.get_connection() as conn:
        conn.executescript(SCHEMA)
        df = pd.read_sql_query(
            "SELECT date, value FROM macro_series WHERE series_id = ? ORDER BY date ASC",
            conn, params=(series_id,),
        )
    if df.empty:
        return df
    df["date"] = pd.to_datetime(df["date"])
    return df.set_index("date")


def get_all_fetched_at() -> dict:
    with storage.get_connection() as conn:
        conn.executescript(SCHEMA)
        rows = conn.execute("SELECT series_id, fetched_at FROM macro_meta").fetchall()
    result = {}
    for series_id, fetched_at in rows:
        try:
            result[series_id] = datetime.fromisoformat(fetched_at)
        except Exception:
            result[series_id] = None
    return result


def ensure_macro_data(force: bool = False, max_age_hours: int = 24, progress_cb=None,
                      *, full_refresh: bool = False) -> dict:
    api_key = config.load_fred_key()
    if not api_key:
        return {"ok": False, "reason": "no_api_key", "refreshed": 0, "failed": {}}

    fetched_at = get_all_fetched_at()
    now = datetime.now(UTC)
    from . import sync_state as sync
    failed_series = {entity for entity, _ in sync.failed_datasets("fred")}
    stale = [
        sid for sid in SERIES
        if force or full_refresh or sid in failed_series or fetched_at.get(sid) is None
        or (now - fetched_at[sid]).total_seconds() > max_age_hours * 3600
    ]
    failed = {}
    for i, sid in enumerate(stale):
        dataset = f"observations:{SERIES[sid]['units_param']}"
        attempt = sync.Attempt("fred", sid, dataset)
        cp = sync.get("fred", sid, dataset)
        try:
            old = get_series_history(sid)
            audit_due = not cp.get("full_audited_at") or (
                now - datetime.fromisoformat(cp["full_audited_at"])).total_seconds() >= 30 * 86400
            audit = full_refresh or audit_due
            start = "1776-07-04" if audit else (old.index.max() - pd.Timedelta(days=400)).date().isoformat() if not old.empty else None
            obs = sync.retry(lambda: fetch_series(sid, api_key, units=SERIES[sid]["units_param"],
                                                   limit=100000, observation_start=start, include_missing=True), attempt)
            attempt.payload(obs)
            if not obs:
                raise ValueError("FRED devolvió una ventana vacía; checkpoint conservado.")
            incoming = pd.DataFrame(obs, columns=["date", "value"]).set_index("date")
            incoming.index = pd.to_datetime(incoming.index)
            changed, new, revised = sync.delta_rows(old, incoming)
            upsert_series(sid, [(d.date().isoformat(), None if pd.isna(v) else float(v)) for d, v in changed.value.items()])
            state = {}
            valid_dates = incoming.loc[incoming.value.notna()].index
            if len(valid_dates):
                state["watermark"] = max(cp.get("watermark", ""), valid_dates.max().date().isoformat())
            if audit:
                state["full_audited_at"] = now.isoformat()
            attempt.finish(sync.change_status(new, revised), state=state, new=new, revised=revised,
                           unchanged=len(incoming) - new - revised,
                           reason="auditoría mensual de revisiones antiguas" if audit else "solape de 400 días para revisiones; incluye valores retirados")
        except Exception as exc:
            _, reason = _classify_error(exc, service="FRED")
            failed[sid] = reason
            attempt.finish("failed", reason=reason)
        if progress_cb:
            progress_cb(i + 1, len(stale), sid)
    storage.record_update_errors("fred_macro", failed)
    return {"ok": True, "refreshed": len(stale) - len(failed), "failed": failed}


# release_id de FRED (no de series) -- solo para series que representan una
# publicación programada y discreta (una vez al mes, en fecha conocida de
# antemano), no una serie que se actualiza a diario como DGS10 o FEDFUNDS:
# ahí "próxima actualización" no es un evento, es continuo.
RELEASE_IDS = {"CPIAUCSL": 10}
RELEASE_DATES_URL = "https://api.stlouisfed.org/fred/release/dates"


def _parse_next_release_date(payload: dict, today: date) -> date | None:
    """Pura: de la respuesta ya parseada (JSON) de /fred/release/dates, la
    primera fecha >= today -- FRED las devuelve ordenadas ascendente al
    pedir sort_order=asc, pero se ordena aquí también por si acaso."""
    dates = sorted(d["date"] for d in payload.get("release_dates", []))
    for d in dates:
        parsed = date.fromisoformat(d)
        if parsed >= today:
            return parsed
    return None


def fetch_next_release_date(series_id: str, api_key: str) -> date | None:
    """Próxima fecha de publicación programada (confirmada por la fuente
    oficial que FRED indexa, ej. BLS para CPI) -- None si `series_id` no
    tiene un release_id mapeado en RELEASE_IDS o si FRED no devuelve ninguna
    fecha futura."""
    release_id = RELEASE_IDS.get(series_id)
    if release_id is None:
        return None
    today = date.today()
    params = {
        "release_id": release_id, "api_key": api_key, "file_type": "json",
        "realtime_start": today.isoformat(), "sort_order": "asc",
        "include_release_dates_with_no_data": "true",
    }
    resp = requests.get(RELEASE_DATES_URL, params=params, timeout=20)
    resp.raise_for_status()
    return _parse_next_release_date(resp.json(), today)


def get_snapshot() -> pd.DataFrame:
    """Una fila por serie: último valor, fecha, variación frente a ~3 meses
    antes (aprox. 63 sesiones para series diarias, o últimas observaciones
    disponibles para series menos frecuentes)."""
    rows = []
    for series_id, meta in SERIES.items():
        history = get_series_history(series_id)
        if history.empty:
            rows.append({
                "series_id": series_id, "label": meta["label"], "unit": meta["unit"],
                "help": meta["help"], "latest_value": None, "latest_date": None, "change_3m": None,
            })
            continue
        latest_date = history.index[-1]
        latest_value = history["value"].iloc[-1]
        change_3m = None
        past = history[history.index <= latest_date - pd.Timedelta(days=90)]
        if not past.empty:
            past_value = past["value"].iloc[-1]
            change_3m = latest_value - past_value
        rows.append({
            "series_id": series_id, "label": meta["label"], "unit": meta["unit"],
            "help": meta["help"], "latest_value": latest_value,
            "latest_date": latest_date.date().isoformat(), "change_3m": change_3m,
        })
    return pd.DataFrame(rows)

sync_state:
"""Shared local checkpoints and measured update events; no alternate scheduler."""

import hashlib
import json
import threading
import time
from dataclasses import dataclass, field
from datetime import UTC, datetime

import pandas as pd
import requests

from gabi.domain.market.sync_events import event_checkpoint, validate_status

from . import storage

SCHEMA = """
CREATE TABLE IF NOT EXISTS sync_checkpoints (
    source TEXT NOT NULL, entity TEXT NOT NULL, dataset TEXT NOT NULL,
    state_json TEXT NOT NULL, PRIMARY KEY (source, entity, dataset)
);
CREATE TABLE IF NOT EXISTS sync_events (
    id INTEGER PRIMARY KEY AUTOINCREMENT, source TEXT NOT NULL, entity TEXT NOT NULL,
    dataset TEXT NOT NULL, at TEXT NOT NULL, event_json TEXT NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_sync_events_at ON sync_events(at);
"""
_PACE_LOCK = threading.Lock()
_NEXT_REQUEST: dict[str, float] = {}


def _pace(source: str, seconds: float) -> None:
    # Shared across workers: SEC's four threads must not each independently burst.
    with _PACE_LOCK:
        now = time.perf_counter()
        delay = max(0., _NEXT_REQUEST.get(source, now) - now)
        _NEXT_REQUEST[source] = now + delay + seconds
    if delay:
        time.sleep(delay)


def get(source: str, entity: str, dataset: str) -> dict:
    with storage.get_connection() as conn:
        conn.executescript(SCHEMA)
        row = conn.execute("SELECT state_json FROM sync_checkpoints WHERE source=? AND entity=? AND dataset=?",
                           (source, entity, dataset)).fetchone()
    return json.loads(row[0]) if row else {}


def due(checkpoint: dict, hours: float, now: datetime | None = None) -> bool:
    if checkpoint.get("status") == "failed" or not checkpoint.get("last_success"):
        return True
    checked = datetime.fromisoformat(checkpoint["last_success"])
    return ((now or datetime.now(UTC)) - checked).total_seconds() >= hours * 3600


def fingerprint(value) -> str:
    safe = json.loads(json.dumps(value, default=str), parse_constant=lambda _: None)
    return hashlib.sha256(json.dumps(safe, sort_keys=True, allow_nan=False).encode()).hexdigest()


def delta_rows(old: pd.DataFrame, new: pd.DataFrame) -> tuple[pd.DataFrame, int, int]:
    """Same observation key changed => revised; unseen key => new. NaNs equal."""
    if new.index.has_duplicates:
        raise ValueError("Observaciones duplicadas en la respuesta.")
    fresh = ~new.index.isin(old.index)
    aligned = old.reindex(index=new.index, columns=new.columns)
    equal = new.eq(aligned) | (new.isna() & aligned.isna())
    changed = ~equal.all(axis=1) & ~fresh
    return new.loc[fresh | changed], int(fresh.sum()), int(changed.sum())


def change_status(new: int, revised: int) -> str:
    # Counts preserve mixed outcomes; revised takes precedence over new.
    return "revised" if revised else "new" if new else "unchanged"


@dataclass
class Attempt:
    source: str
    entity: str
    dataset: str
    calls: int = 0
    payload_bytes: int = 0  # decoded payload; explicitly not wire bytes
    started: float = field(default_factory=time.perf_counter)
    cpu_started: float = field(default_factory=time.thread_time)

    def payload(self, value) -> None:
        self.payload_bytes += len(json.dumps(value, default=str).encode())

    def finish(self, status: str, *, state: dict | None = None, new: int = 0, revised: int = 0,
               unchanged: int = 0, reason: str = "", skipped: bool = False) -> dict:
        validate_status(status)
        now = datetime.now(UTC).isoformat()
        previous = get(self.source, self.entity, self.dataset)
        event, checkpoint = event_checkpoint(self.source, self.entity, self.dataset, previous, now,
            status=status, calls=self.calls, payload_bytes=self.payload_bytes,
            seconds=time.perf_counter() - self.started, cpu_seconds=time.thread_time() - self.cpu_started,
            state=state, new=new, revised=revised, unchanged=unchanged, reason=reason, skipped=skipped)
        with storage.get_connection() as conn:
            conn.executescript(SCHEMA)
            if not skipped:
                conn.execute("INSERT INTO sync_checkpoints VALUES (?,?,?,?) "
                             "ON CONFLICT(source,entity,dataset) DO UPDATE SET state_json=excluded.state_json",
                             (self.source, self.entity, self.dataset, json.dumps(checkpoint)))
            conn.execute("INSERT INTO sync_events(source,entity,dataset,at,event_json) VALUES (?,?,?,?,?)",
                         (self.source, self.entity, self.dataset, now, json.dumps(event)))
            conn.commit()
        return event


def retry(call, attempt: Attempt, *, attempts: int = 3, pace: float = .25):
    """Bounded retry; only transient network/rate failures. Never checkpoint here."""
    from .data_fetch import RETRYABLE_CATEGORIES, _classify_error

    for i in range(attempts):
        if pace:
            _pace(attempt.source, max(.15, pace) if attempt.source == "sec" else pace)
        attempt.calls += 1
        try:
            return call()
        except Exception as exc:
            category, _ = _classify_error(exc)
            response = getattr(exc, "response", None)
            transient = (category in RETRYABLE_CATEGORIES or isinstance(exc, (requests.Timeout, requests.ConnectionError))
                         or (response is not None and response.status_code >= 500))
            if not transient or i + 1 == attempts:
                raise
            # Respect Retry-After seconds, bounded to keep a failed run resumable.
            delay = min(30., 1.5 * 2 ** i)
            if response is not None:
                try:
                    delay = min(30., max(delay, float(response.headers.get("Retry-After", delay))))
                except ValueError:
                    pass
            time.sleep(delay)
    raise RuntimeError("No se completó la petición.")


def events_since(event_id: int = 0) -> list[dict]:
    with storage.get_connection() as conn:
        conn.executescript(SCHEMA)
        rows = conn.execute("SELECT event_json FROM sync_events WHERE id>? ORDER BY id", (event_id,)).fetchall()
    return [json.loads(r[0]) for r in rows]


def latest_event_id() -> int:
    with storage.get_connection() as conn:
        conn.executescript(SCHEMA)
        return int(conn.execute("SELECT COALESCE(MAX(id),0) FROM sync_events").fetchone()[0])


def failed_datasets(source: str) -> set[tuple[str, str]]:
    with storage.get_connection() as conn:
        conn.executescript(SCHEMA)
        rows = conn.execute("SELECT entity,dataset FROM sync_checkpoints WHERE source=? "
                            "AND json_extract(state_json,'$.status')='failed'", (source,)).fetchall()
    return set(rows)


def totals(events: list[dict]) -> dict:
    return {**{k: sum(e.get(k, 0) for e in events)
               for k in ("calls", "payload_bytes", "seconds", "cpu_seconds", "new", "revised", "unchanged")},
            "statuses": {s: sum(e["status"] == s for e in events) for s in ("new", "revised", "unchanged", "failed")},
            "skipped": sum(e["skipped"] for e in events)}
